import React from 'react';
import Header from './Header';
import Footer from './Footer';
import ScrollTracker from '../common/ScrollTracker';

const Layout = ({ children }) => (
  <ScrollTracker>
    <Header />
    <main>{children}</main>
    <Footer />
  </ScrollTracker>
);

export default Layout;
